class Solution {
    public int findMinDifference(List<String> timePoints){
        int[] minutes=new int[timePoints.size()];
        for(int i=0;i<minutes.length;i++){
            String value=timePoints.get(i);
            minutes[i]=Integer.parseInt(value.substring(0,2))*60+Integer.parseInt(value.substring(3));
        }
        Arrays.sort(minutes);
        int best=minutes[0]+1440-minutes[minutes.length-1];
        for(int i=1;i<minutes.length;i++)best=Math.min(best,minutes[i]-minutes[i-1]);
        return best;
    }
}

code.kotlin:
class Solution {
    fun findMinDifference(timePoints:List<String>):Int{
        val minutes=timePoints.map{
            it.substring(0,2).toInt()*60+it.substring(3).toInt()
        }.sorted();
        var best=minutes[0]+1440-minutes.last();
        for(i in 1 until minutes.size)best=minOf(best,minutes[i]-minutes[i-1]);
        return best
    }
}

code.cpp:
class Solution {
    public: int findMinDifference(vector<string>& timePoints){
        vector<int> minutes;
        for(string value:timePoints)minutes.push_back(stoi(value.substr(0,2))*60+stoi(value.substr(3)));
        sort(minutes.begin(),minutes.end());
        int best=minutes[0]+1440-minutes.back();
        for(int i=1;i<(int)minutes.size();++i)best=min(best,minutes[i]-minutes[i-1]);
        return best;
    }
};
